insert into public.announcements (id, title, body, category, severity, published_at, expires_at, pinned, attachments, published)
values ('g1-2027-applications', 'Grade 1 admissions for 2027 now open', 'Applications for admission to Grade 1 in the 2027 academic year are now open under Ministry Circular No. 25/2026. Children must complete five years of age by 31 January 2027. Applications must be submitted by registered post to at least six schools, including at least three Provincial Council schools near your residence, in order of preference, and must be received on or before 30 July 2026.', 'Admissions', 'urgent', '2026-06-30', '2026-07-30', true, '[]'::jsonb, true)
on conflict (id) do update set
  title = excluded.title, body = excluded.body, category = excluded.category,
  severity = excluded.severity, published_at = excluded.published_at,
  expires_at = excluded.expires_at, pinned = excluded.pinned,
  attachments = excluded.attachments, published = excluded.published
where public.announcements.updated_at = public.announcements.created_at;
