insert into public.articles (slug, title, excerpt, body, category, published_at, read_minutes, hero_slot_id, published)
values ('national-cadet-band-championship', 'Nalanda College Reclaims National Cadet Band Championship After 25 Years', 'The Western Cadet Band of Nalanda College has secured the championship at the All Island competition.', ARRAY['The Western Cadet Band of Nalanda College has achieved a remarkable milestone, securing the Championship at the All Island Cadet Band Championship.', 'The title returns to the college after an absence of 25 years, and reflects the sustained work of the band''s instructors and the cadets who have drilled through the year.', 'Cadet banding remains one of the college''s most demanding extra-curricular commitments, requiring regular early-morning practice and a high standard of musical discipline.']::text[], 'Achievements', '2026-10-01', 2, null, true)
on conflict (slug) do update set
  title = excluded.title, excerpt = excluded.excerpt, body = excluded.body,
  category = excluded.category, published_at = excluded.published_at,
  read_minutes = excluded.read_minutes, published = excluded.published
where public.articles.updated_at = public.articles.created_at;
insert into public.articles (slug, title, excerpt, body, category, published_at, read_minutes, hero_slot_id, published)
values ('first-carbon-footprint-neutral-school', 'Sri Lanka''s First Carbon Footprint Neutral School', 'The college is officially recognised as Sri Lanka''s first carbon footprint neutral school.', ARRAY['Nalanda College has been officially recognised as Sri Lanka''s first carbon footprint neutral school, creating another unique record for the institution.', 'The recognition follows sustained work on the environmental footprint of a campus of more than four thousand students, and places the college among the first schools in the country to reach this standard.', 'It is a marker of how the second century of the school is being framed: continuity of Buddhist scholarly tradition alongside a contemporary responsibility to the country it serves.']::text[], 'Achievements', '2026-06-05', 2, null, true)
on conflict (slug) do update set
  title = excluded.title, excerpt = excluded.excerpt, body = excluded.body,
  category = excluded.category, published_at = excluded.published_at,
  read_minutes = excluded.read_minutes, published = excluded.published
where public.articles.updated_at = public.articles.created_at;
insert into public.articles (slug, title, excerpt, body, category, published_at, read_minutes, hero_slot_id, published)
values ('hostel-library-opening', 'Hostel Library Opening Ceremony', 'The Hostel Library was officially opened, introducing a new space dedicated to learning, reading and academic enrichment.', ARRAY['The Hostel Library was officially opened, introducing a new space dedicated to learning, reading and academic enrichment.', 'The facility gives boarders a dedicated place to study within the hostel, reducing the need to travel to other facilities during study periods.', 'The newly established space is part of continued investment in boarding life at the college.']::text[], 'School News', '2026-09-17', 1, null, true)
on conflict (slug) do update set
  title = excluded.title, excerpt = excluded.excerpt, body = excluded.body,
  category = excluded.category, published_at = excluded.published_at,
  read_minutes = excluded.read_minutes, published = excluded.published
where public.articles.updated_at = public.articles.created_at;
insert into public.articles (slug, title, excerpt, body, category, published_at, read_minutes, hero_slot_id, published)
values ('centennial-swimming-fiesta', 'Nalanda Centennial Swimming Fiesta', 'A celebration of speed, grit and sporting excellence, held on 10 September at the Centennial Swimming Fiesta.', ARRAY['The spirit of sporting excellence took centre stage at the Nalanda Centennial Swimming Fiesta, held on 10 September.', 'The meet formed part of the centenary programme of sporting events, extending a tradition that includes athletics, boxing, aquatics and rugby.', 'The Old Nalandians'' Sports Club, established in 1967, continues to organise major fixtures including the Centennial Rugby Fiesta and the Centennial Boxing Fiesta.']::text[], 'School News', '2026-09-11', 2, null, true)
on conflict (slug) do update set
  title = excluded.title, excerpt = excluded.excerpt, body = excluded.body,
  category = excluded.category, published_at = excluded.published_at,
  read_minutes = excluded.read_minutes, published = excluded.published
where public.articles.updated_at = public.articles.created_at;
insert into public.articles (slug, title, excerpt, body, category, published_at, read_minutes, hero_slot_id, published)
values ('ranaviru-upahara-2026', 'Ranaviru Upahara 2026', 'The Nalanda Junior Old Boys'' Association presents Ranaviru Upahara 2026, honouring war heroes.', ARRAY['The Nalanda Junior Old Boys'' Association proudly presents Ranaviru Upahara 2026, a special gathering organised to honour the courage, dedication and sacrifice of the fallen.', 'The commemoration is held in tribute to Nalandian war heroes who made the supreme sacrifice in defence of the country.', 'Ranaviru Upahara 2026 was held as a dedicated remembrance, with a further tribute event for the war heroes.']::text[], 'School News', '2026-08-06', 1, null, true)
on conflict (slug) do update set
  title = excluded.title, excerpt = excluded.excerpt, body = excluded.body,
  category = excluded.category, published_at = excluded.published_at,
  read_minutes = excluded.read_minutes, published = excluded.published
where public.articles.updated_at = public.articles.created_at;
insert into public.articles (slug, title, excerpt, body, category, published_at, read_minutes, hero_slot_id, published)
values ('sports-icon-of-the-century', 'Old Nalandians Sports Club - Nalanda Sports Icon of the Century', 'The Old Nalandians Sports Club is recognised as Nalanda Sports Icon of the Century.', ARRAY['The legendary history of Nalanda College has been written in part by its Old Nalandians, and the Sports Icon of the Century award recognises the club''s contribution to that history.', 'Founded in 1967, the Old Nalandians'' Sports Club continues to organise school fixtures and alumni sporting events across rugby, boxing and other codes.']::text[], 'Achievements', '2026-06-29', 1, null, true)
on conflict (slug) do update set
